function useDemoStorage<T>(key: string, initialValue: T, hydrate?: (value: T) => T) {
  const [value, setValue] = useState<T>(initialValue); const [ready, setReady] = useState(false);
  useEffect(() => { const timer = window.setTimeout(() => { try { const saved = window.localStorage.getItem(key); if (saved) { const parsed = JSON.parse(saved) as T; setValue(hydrate ? hydrate(parsed) : parsed); } } catch { /* local fallback */ } setReady(true); }, 0); return () => window.clearTimeout(timer); }, [hydrate, key]);
  useEffect(() => { if (ready) window.localStorage.setItem(key, JSON.stringify(value)); }, [key, ready, value]);
  return [value, setValue] as const;
}
function Tone({ children, tone = "neutral" }: { children: ReactNode; tone?: string }) { return <span className={`buho-tone tone-${tone}`}>{children}</span>; }
function similarityLabel(level: MatchLevel) { return `${level} similitud`; }
function matchStatusLabel(status: MatchStatus) { return status === "Convertida en caso" ? "Pasada a caso" : status; }
function matchStatusTone(status: MatchStatus) { return `match-${status.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replaceAll(" ", "-")}`; }
function shortDisplayDate(value: string) { const date = new Date(`${value}T12:00:00`); return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat("es-CL", { day: "2-digit", month: "short", year: "numeric" }).format(date).replaceAll(" de ", " "); }
function stageTone(stage: CaseStage) { return `stage-${stage.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "")}`; }
function formatToday() { return new Intl.DateTimeFormat("es-CL", { timeZone: "America/Santiago", weekday: "long", day: "numeric", month: "short", year: "numeric" }).format(new Date()).toUpperCase().replaceAll(" DE ", " "); }
function inferBrandType(value: string, index = 0): BrandType { const normalized = value.toLowerCase(); if (normalized.includes("figurativa")) return "Figurativa"; if (normalized.includes("mixta") || normalized.includes("logo")) return "Mixta"; if (normalized.includes("denominativa")) return "Denominativa"; return (["Mixta", "Denominativa", "Figurativa"] as BrandType[])[index % 3]; }
function normalizeBrand(brand: Brand, index = 0): Brand { return { ...brand, status: String(brand.status) === "Pausada" || String(brand.status) === "Sin monitoreo" ? "Sin monitoreo" : "En monitoreo", registrationState: brand.registrationState ?? (index % 6 === 1 ? "En trámite" : index % 9 === 2 ? "Rechazada" : "Registrada"), type: brand.type ?? inferBrandType(brand.visual ?? brand.name, index) }; }
function normalizeMatch(match: Match, index = 0): Match { const legacyStatus = String(match.status); const tracked = initialBrands.find((brand) => brand.id === match.brandId); return { ...match, status: legacyStatus === "Pendiente" ? "Pendiente de clasificación" : legacyStatus === "En observación" ? "En seguimiento" : legacyStatus as MatchStatus, brandType: match.brandType ?? inferBrandType(match.brand, index), brandClasses: match.brandClasses ?? tracked?.classes ?? "29, 30, 35", foundType: match.foundType ?? inferBrandType(match.found, index + 1), foundClasses: match.foundClasses ?? (index % 2 ? "30, 35" : "29, 30, 35") }; }
function enrichedNotices(source: Notice[]) { const serverNotices = source.filter((notice) => notice.id !== "NO-108").map((notice) => { const curated = initialNotices.find((item) => item.id === notice.id); return curated ? { ...notice, ...curated, status: notice.status } : { ...notice, urgency: notice.urgency as MatchLevel, matchId: notice.matchId ?? (notice.title.includes("TERRA") ? "CO-2479" : notice.title.includes("CASA") ? "CO-2472" : notice.title.includes("NOVA") ? "CO-2481" : undefined) }; }); return [...serverNotices, ...initialNotices.filter((item) => !serverNotices.some((notice) => notice.id === item.id))]; }
function mergeInitialMatches(source: Match[]) { return [...source.map(normalizeMatch), ...initialMatches.filter((item) => !source.some((match) => match.id === item.id))]; }
function normalizeCases(source: LegalCase[]) { return source.map((item) => { const legacyStage = String(item.stage); const stage: CaseStage = legacyStage === "Concluido" ? "Concluido" : legacyStage === "Preparación" || legacyStage === "Esperando confirmación de cliente" ? "Esperando confirmación de cliente" : "En seguimiento"; return { ...item, deadline: /2026|2027/.test(item.deadline) ? item.deadline : `${item.deadline} 2026`, deadlineDescription: item.deadlineDescription ?? (stage === "En seguimiento" ? legalDeadlineOptions[3] : legalDeadlineOptions[0]), stage } as LegalCase; }); }

