  const monthName = new Intl.DateTimeFormat("es-CL", { month: "long", year: "numeric" }).format(cursor).replace(/^./, (letter) => letter.toUpperCase());
  const events = datedCases.filter(({ date }) => date.getFullYear() === year && date.getMonth() === month);
