function MatchDrawer({ match, onClose, onContact, onReview }: { match: Match; onClose: () => void; onContact: () => void; onReview: (status: MatchStatus) => void }) {
  const leftRegistration = match.brandRegistration ?? initialBrands.find((brand) => brand.id === match.brandId)?.registration ?? "Sin registro"; const officialRegistration = match.officialRegistration ?? `DO-${match.application}`;
  const comparisonRows = (side: "brand" | "found") => [{ label: "Tipo de marca", value: side === "brand" ? match.brandType : match.foundType }, { label: "Fonético", value: side === "brand" ? match.brand : match.found }, { label: "Conceptual", value: "Alimentos y servicios relacionados" }, { label: "RUT", value: side === "brand" ? match.rut : match.applicantRut }, { label: "N.º registro (DO)", value: side === "brand" ? leftRegistration : officialRegistration }, { label: "N.º solicitud (INAPI)", value: side === "brand" ? "—" : match.application }, { label: "Clases de Niza", value: matchClasses(match, side) }];
  return <DrawerShell eyebrow={`${match.id} · ${match.source}`} onClose={onClose} title="Revisión de vigilancia" wide><div className="buho-drawer-scroll buho-drawer-match"><div className="buho-match-summary"><Tone tone={match.level.toLowerCase()}>{similarityLabel(match.level)}</Tone><div><strong>{similarityLabel(match.level)}</strong><small>{match.status} · {match.date}</small></div><a className="buho-inapi-link" href={match.officialUrl || INAPI_SEARCH_URL} rel="noreferrer" target="_blank">Ver en INAPI ↗</a></div><div className="buho-side-by-side"><article><span>MARCA EN SEGUIMIENTO</span><div className="buho-mark-card"><LogoMark name={match.brand} type={match.brandType} /></div><dl>{comparisonRows("brand").map((row) => <div key={row.label}><dt>{row.label}</dt><dd>{row.value}</dd></div>)}</dl></article><i>↔</i><article><span>MARCA VIGILADA</span><div className="buho-mark-card is-found"><LogoMark name={match.found} type={match.foundType} /></div><dl>{comparisonRows("found").map((row) => <div key={row.label}><dt>{row.label}</dt><dd>{row.value}</dd></div>)}</dl></article></div><section className="buho-explanation"><span className="buho-overline">POR QUÉ SE DETECTÓ · RESULTADO MOCK</span><p>El signo encontrado comparte elementos visuales, fonéticos y semánticos con la marca en seguimiento, además de coincidir en clases relacionadas. Los tres análisis son demostrativos mientras se conectan los motores reales.</p></section></div><footer className="buho-drawer-actions buho-review-actions"><button onClick={() => onReview("Descartada")} type="button">Descartar</button><button onClick={() => onReview("En seguimiento")} type="button">Mantener en seguimiento</button><a className="buho-action-link" href="/reports/informe-vigilancia-demo.pdf" rel="noreferrer" target="_blank">Abrir informe PDF</a><button onClick={onContact} type="button">Contactar cliente</button><button className="buho-primary" onClick={() => onReview("Convertida en caso")} type="button">Convertir en caso</button></footer></DrawerShell>;
}
function CaseDrawer({ item, onChangeOwner, onClose, onContact, onDiscard, onMove, onOpenMatch, users }: { item: LegalCase; onChangeOwner: (owner: string) => void; onClose: () => void; onContact: () => void; onDiscard: () => void; onMove: (stage: CaseStage) => void; onOpenMatch: (id: string) => void; users: DemoUser[] }) {
  const [confirmingDiscard, setConfirmingDiscard] = useState(false);
  const nextStage = stages[stages.indexOf(item.stage) + 1];
  return <DrawerShell eyebrow={item.id} onClose={onClose} title={item.title}><div className="buho-drawer-scroll"><div className="buho-case-hero"><Tone tone={item.priority.toLowerCase()}>{item.priority}</Tone><Tone tone={stageTone(item.stage)}>{item.stage}</Tone><h3>{item.brand}</h3><p>{item.client}</p></div><section className="buho-detail-grid"><div><span>Abogado a cargo del caso</span><select aria-label="Cambiar abogado a cargo del caso" onChange={(event) => onChangeOwner(event.target.value)} value={item.owner}>{users.map((user) => <option key={user.id}>{user.name}</option>)}</select></div><div className="buho-deadline-detail"><span>Próximo plazo</span><strong>{item.deadline}</strong><small>{item.deadlineDescription}</small></div><div><span>Vigilancia de origen</span><strong>{item.sourceMatch ?? "Sin vigilancia vinculada"}</strong></div><div><span>Etapa</span><select aria-label="Mover caso a etapa" onChange={(event) => onMove(event.target.value as CaseStage)} value={item.stage}>{stages.map((stage) => <option key={stage}>{stage}</option>)}</select></div></section><section className="buho-case-section"><header><h3>Tareas</h3><button type="button">Agregar</button></header><label><input defaultChecked type="checkbox" />Revisar antecedentes de la publicación</label><label><input type="checkbox" />Confirmar instrucciones con cliente</label><label><input type="checkbox" />Preparar oposición</label></section><section className="buho-case-section buho-history"><header><h3>Historial del caso</h3><span>Solo lectura</span></header><p>19 ago 2026 · Vigilancia {item.sourceMatch ?? "manual"} revisada</p><p>20 ago 2026 · Cliente informado del hallazgo</p><p>22 ago 2026 · Caso movido a {item.stage}</p></section></div>{confirmingDiscard && <div aria-label="Confirmar descarte del caso" className="buho-case-confirmation" role="alertdialog"><div><strong>¿Descartar este caso?</strong><small>El caso saldrá de las vistas activas y la vigilancia de origen quedará descartada.</small></div><button onClick={() => setConfirmingDiscard(false)} type="button">Cancelar</button><button className="is-danger" onClick={() => { onDiscard(); setConfirmingDiscard(false); }} type="button">Sí, descartar caso</button></div>}<footer className="buho-drawer-actions"><button onClick={onClose} type="button">Cerrar</button><button onClick={() => setConfirmingDiscard(true)} type="button">Descartar caso</button>{item.sourceMatch && <button onClick={() => onOpenMatch(item.sourceMatch!)} type="button">Ver vigilancia</button>}<button onClick={onContact} type="button">Contactar cliente</button>{nextStage && <button className="buho-primary" onClick={() => onMove(nextStage)} type="button">Mover a {nextStage} <span>→</span></button>}</footer></DrawerShell>;
}
function NoticeDrawer({ notice, onClose, onChange, onCopy }: { notice: Notice; onClose: () => void; onChange: (patch: Partial<Notice>) => void; onCopy: (text: string, label: string) => void }) { return <DrawerShell eyebrow={`${notice.id} · ${notice.brand}`} onClose={onClose} title="Correo prehecho" wide><div className="buho-drawer-scroll"><div className="buho-mail-context"><Tone tone={notice.urgency.toLowerCase()}>{similarityLabel(notice.urgency)}</Tone><div><strong>{notice.title}</strong><small>Destinatario sugerido: contacto del cliente</small></div></div><label className="buho-mail-field">Asunto<div><input onChange={(event) => onChange({ subject: event.target.value })} value={notice.subject} /><button onClick={() => onCopy(notice.subject, "Asunto")} type="button">Copiar asunto</button></div></label><label className="buho-mail-field">Cuerpo del correo<textarea onChange={(event) => onChange({ body: event.target.value })} rows={12} value={notice.body} /><button onClick={() => onCopy(notice.body, "Correo")} type="button">Copiar correo</button></label></div><footer className="buho-drawer-actions"><button onClick={onClose} type="button">Cerrar</button><button onClick={() => { onChange({ status: "Gestionada" }); onClose(); }} type="button">Marcar como enviado</button><button className="buho-primary" onClick={() => onCopy(notice.body, "Correo")} type="button">Copiar correo <span>→</span></button></footer></DrawerShell>; }
